import { spawnSync } from 'node:child_process';
import { writeFileSync, readFileSync } from 'node:fs';
import path from 'node:path';
import { pathToFileURL } from 'node:url';

export async function gate({ referenceDir, submissionDir }) {
  try {
    const pinnedPath = path.join(referenceDir, 'pinned-test-cases.txt');
    let pinnedSrc;
    try {
      pinnedSrc = readFileSync(pinnedPath, 'utf8');
    } catch (e) {
      return { accept: false, reason: 'Could not read pinned-test-cases.txt: ' + e.message };
    }

    const testNameMatches = pinnedSrc.match(/^\s*test\(/gm) || [];
    const expectedTestCount = testNameMatches.length;
    if (expectedTestCount === 0) {
      return { accept: false, reason: 'Pinned test file contained no discoverable test cases; cannot grade.' };
    }

    const answerPath = path.join(submissionDir, 'answer.mjs');
    try {
      readFileSync(answerPath);
    } catch (e) {
      return { accept: false, reason: 'submissionDir/answer.mjs does not exist or is unreadable: ' + e.message };
    }

    const answerUrl = pathToFileURL(answerPath).href;

    const harnessSource = [
      "import { test } from 'node:test';",
      "import assertModule from 'node:assert/strict';",
      "const assert = assertModule;",
      "try { Object.freeze(assert); } catch (e) {}",
      "import { dedupeSorted } from " + JSON.stringify(answerUrl) + ";",
      "",
      pinnedSrc,
      ""
    ].join('\n');

    const harnessPath = path.join(referenceDir, 'gate-harness.mjs');
    writeFileSync(harnessPath, harnessSource, 'utf8');

    const result = spawnSync(process.execPath, ['--test', harnessPath], {
      encoding: 'utf8',
      timeout: 15000,
      killSignal: 'SIGKILL',
      maxBuffer: 10 * 1024 * 1024
    });

    if (result.error) {
      return { accept: false, reason: 'Failed to execute submission harness: ' + result.error.message };
    }

    const stdout = result.stdout || '';
    const stderr = result.stderr || '';

    if (result.signal === 'SIGKILL') {
      return { accept: false, reason: 'Submission harness was killed (timeout, possible infinite loop or hang).' };
    }

    const passMatch = stdout.match(/#\s*pass\s+(\d+)/);
    const failMatch = stdout.match(/#\s*fail\s+(\d+)/);
    const testsMatch = stdout.match(/#\s*tests\s+(\d+)/);

    if (!passMatch || !failMatch || !testsMatch) {
      return { accept: false, reason: 'Could not parse a test summary from the harness output; the submission may have interfered with the test runner or crashed before tests ran.\n---stdout(trunc)---\n' + stdout.slice(0, 1500) + '\n---stderr(trunc)---\n' + stderr.slice(0, 1500) };
    }

    const passCount = parseInt(passMatch[1], 10);
    const failCount = parseInt(failMatch[1], 10);
    const testsCount = parseInt(testsMatch[1], 10);

    if (failCount !== 0) {
      return { accept: false, reason: failCount + ' of ' + testsCount + ' pinned test case(s) failed against this submission.' };
    }

    if (result.status !== 0) {
      return { accept: false, reason: 'Harness process exited with non-zero status ' + result.status + ' despite reported pass=' + passCount + ' fail=' + failCount + '; treating as failure.' };
    }

    if (testsCount !== expectedTestCount || passCount !== expectedTestCount) {
      return { accept: false, reason: 'Expected exactly ' + expectedTestCount + ' pinned tests to genuinely run and pass, but observed tests=' + testsCount + ' pass=' + passCount + '. This may indicate the submission short-circuited execution (e.g. early process exit) or otherwise interfered with the test runner.' };
    }

    return { accept: true, reason: 'All ' + expectedTestCount + ' pinned test cases (including the randomized oracle property check) executed genuinely against this submission\'s own dedupeSorted export and passed.' };
  } catch (e) {
    return { accept: false, reason: 'Gate encountered an unexpected internal error: ' + (e && e.message ? e.message : String(e)) };
  }
}

