export function dedupeSorted(arr) {
  const out = [];
  let i = 0;
  while (i < arr.length) {
    out.push(arr[i]);
    let j = i + 1;
    while (j < arr.length && arr[j] === arr[i]) j++;
    i = j;
  }
  return out;
}

